import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;

public class OnlineStockSpanTest {

    @Test
    public void next_0_Returns1() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int actual = onlineStockSpan.next(0);
        assertEquals(1, actual);
    }

    @Test
    public void next_PositiveNumber_Returns1() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int actual = onlineStockSpan.next(10);
        assertEquals(1, actual);
    }

    @Test
    public void next_NegativeNumber_Returns1() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int actual = onlineStockSpan.next(-5);
        assertEquals(1, actual);
    }

    @Test
    public void calculateSpans_EmptyArray_ReturnsEmptyArray() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] actual = onlineStockSpan.calculateSpans(new int[0]);
        assertArrayEquals(new int[0], actual);
    }

    @Test
    public void calculateSpans_SingleElement_ReturnsArrayWithOneElement() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10};
        int[] actual = onlineStockSpan.calculateSpans(prices);
        assertArrayEquals(new int[]{1}, actual);
    }

    @Test
    public void calculateSpans_MultipleElements_ReturnsCorrectSpans() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 7, 5, 8, 11, 9};
        int[] expected = new int[]{1,2,3,4,5,6};
        int[] actual = onlineStockSpan.calculateSpans(prices);
        assertArrayEquals(expected, actual);
    }

    @Test
    public void next_MultipleTimes_ReturnsIncreasingSpans() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {10, 7, 5, 8, 11, 9};
        for (int i = 0; i < prices.length - 1; i++) {
            onlineStockSpan.next(prices[i]);
            assertEquals(i + 2, onlineStockSpan.next(prices[i + 1]));
        }
    }

    @Test
    public void next_Overflow_Returns0() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int[] prices = {Integer.MAX_VALUE};
        for (int i = 0; i < prices.length - 1; i++) {
            onlineStockSpan.next(prices[i]);
        }
        assertEquals(0, onlineStockSpan.next(prices[prices.length - 1]));
    }

}
